mapper.select:
SELECT c.capability_version FROM capability_version c
JOIN configuration_head h ON h.tenant_id=c.tenant_id AND h.config_id=c.config_id AND h.current_version=c.capability_version AND h.kind='CAPABILITY' AND h.project_id <=> c.project_id
JOIN agent_publication_record r ON r.tenant_id=c.tenant_id AND r.resource_id=c.capability_version AND r.kind='AUTHOR' AND r.content_sha256=c.content_sha256 AND r.project_id <=> c.project_id
WHERE c.project_id <=> #{projectId} AND c.kind=#{capabilityKind} AND c.kind IN ('TOOL','SKILL') AND c.capability_version > #{afterId}
ORDER BY c.capability_version LIMIT #{scanLimit}
